diff --git a/tests/notes.test.mjs b/tests/notes.test.mjs
index b43658e..baae8bb 100644
--- a/tests/notes.test.mjs
+++ b/tests/notes.test.mjs
@@ -32,3 +32,54 @@ test('a note can be updated and deleted', async () => {
   assert.equal((await call('DELETE', `/notes/${note.id}`, 'ayse')).status, 204);
   assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 404);
 });
+
+// Depo sunucu başına tek; her test kendine özgü önek kullanır ve q ile sonucu ayırır.
+const titles = async (qs) => (await (await call('GET', `/notes?${qs}`, 'ayse')).json()).map((n) => n.title);
+const seed = (...ts) => Promise.all(ts.map((title) => call('POST', '/notes', 'ayse', { title })));
+
+test('S-01.1 sort=title Türkçe alfabe sırasıyla sıralar', async () => {
+  await seed('zS1 Zeytin', 'zS1 Çay', 'zS1 Ilık', 'zS1 İnci', 'zS1 Şeker', 'zS1 Ayva', 'zS1 Ödev', 'zS1 Ağaç');
+  assert.deepEqual(await titles('sort=title&q=zS1'),
+    ['zS1 Ağaç', 'zS1 Ayva', 'zS1 Çay', 'zS1 Ilık', 'zS1 İnci', 'zS1 Ödev', 'zS1 Şeker', 'zS1 Zeytin']);
+});
+
+test('S-01.2 sort=title büyük/küçük harfi yok sayar', async () => {
+  await seed('zS2 bal', 'zS2 Armut', 'zS2 çilek');
+  assert.deepEqual(await titles('sort=title&q=zS2'), ['zS2 Armut', 'zS2 bal', 'zS2 çilek']);
+});
+
+test('S-02.1 q büyük/küçük harf duyarsız arar', async () => {
+  await seed('zS3 Toplantı notu', 'zS3 Market');
+  assert.deepEqual(await titles('q=ZS3 TOPLANTI'), ['zS3 Toplantı notu']);
+});
+
+test('S-02.2 q Türkçe İ/I ve ı/i eşlemesini doğru yapar', async () => {
+  await seed('zS4 İstanbul', 'zS4 ılık süt', 'zS4 Iğdır');
+  assert.deepEqual(await titles('sort=title&q=zS4 istanbul'), ['zS4 İstanbul']);
+  assert.deepEqual(await titles('sort=title&q=zS4 ILIK'), ['zS4 ılık süt']);
+  assert.deepEqual(await titles('sort=title&q=zS4 iğdır'), []);
+});
+
+test('S-02.3 q sadece başlığa bakar, gövdeye bakmaz', async () => {
+  await call('POST', '/notes', 'ayse', { title: 'zS5 a', body: 'gizlikelime' });
+  assert.deepEqual(await titles('q=gizlikelime'), []);
+});
+
+test('S-03.1 sort ve q birlikte çalışır', async () => {
+  await seed('zS6 Muz', 'zS6 elma', 'zS6 Kiraz', 'zS6 Armut');
+  assert.deepEqual(await titles('sort=title&q=zS6 '), ['zS6 Armut', 'zS6 elma', 'zS6 Kiraz', 'zS6 Muz']);
+  assert.deepEqual(await titles('sort=title&q=zS6 m'), ['zS6 Muz']);
+});
+
+test('S-04.1 parametresiz liste eskisi gibi, boş q filtre değil', async () => {
+  await seed('zS7 x');
+  const all = await titles('');
+  assert.ok(all.includes('zS7 x'));
+  assert.deepEqual(await titles('q='), all);
+});
+
+test('S-04.2 desteklenmeyen sort 400 döner', async () => {
+  const r = await call('GET', '/notes?sort=body', 'ayse');
+  assert.equal(r.status, 400);
+  assert.ok((await r.json()).error);
+});

