+++ b/tests/notes.test.mjs
@@ -26,6 +26,20 @@ test('a note without a title is rejected', async () => {
   assert.equal((await call('POST', '/notes', 'ayse', { body: 'x' })).status, 400);
 });

+test('notes can be sorted by title (Turkish alphabet) and searched case-insensitively', async () => {
+  for (const title of ['Zeytin', 'Çorba', 'Ilık', 'İstanbul', 'Arı', 'Ördek', 'Işık']) {
+    await call('POST', '/notes', 'ayse', { title });
+  }
+  const sorted = await (await call('GET', '/notes?sort=title', 'ayse')).json();
+  const expected = ['Arı', 'Çorba', 'Ilık', 'Işık', 'İstanbul', 'Ördek', 'Zeytin'];
+  assert.deepEqual(sorted.map((n) => n.title).filter((t) => expected.includes(t)), expected);
+
+  const found = await (await call('GET', '/notes?q=' + encodeURIComponent('İSTANBUL'), 'ayse')).json();
+  assert.deepEqual(found.map((n) => n.title), ['İstanbul']);
+  const both = await (await call('GET', '/notes?sort=title&q=' + encodeURIComponent('ık'), 'ayse')).json();
+  assert.deepEqual(both.map((n) => n.title), ['Ilık', 'Işık']);
+});
+
 test('a note can be updated and deleted', async () => {
   const note = await (await call('POST', '/notes', 'ayse', { title: 'Taslak' })).json();
   assert.equal((await (await call('PATCH', `/notes/${note.id}`, 'ayse', { title: 'Son' })).json()).title, 'Son');

